lines+=['','## Native and train-only priors','','| Baseline | N | Accuracy | Conditional CE | Brier | ECE | Top ties |','|---|---:|---:|---:|---:|---:|---:|']
for name in ('native_K1','native_K2','prior_uniform','prior_global','prior_candidate_count'):
 a=s[name]['all'];lines.append(f"| {name} | {a['n']} | {a['accuracy']:.4f} | {a['conditional_cross_entropy']:.4f} | {a['brier']:.4f} | {a['ece_10']:.4f} | {a['top_tie_count']} |")
lines+=['','## All probe applications: four natural groups and no-tie','','Group membership comes from the same historical A6000 native K1/K2 trajectories. Rows show accuracy (N); natural no-tie means no top tie at either natural K1 or K2. Complete per-question predictions, probabilities, candidate values, first tie and paired native groups are retained.','','| Probe application | Rescue | Damage | Stable correct | Stable wrong | Natural no tie | Fixed-wrong mean | Dynamic mean |','|---|---:|---:|---:|---:|---:|---:|---:|']
for name in sorted(k for k in s if '_evalK' in k):
 a=s[name];fmt=lambda z:f"{z['accuracy']:.3f} ({z['n']})" if z['n'] else 'NA';g=a['groups'];v=a['all'];lines.append(f"| {name} | {fmt(g['rescue'])} | {fmt(g['damage'])} | {fmt(g['stable_correct'])} | {fmt(g['stable_wrong'])} | {fmt(a['natural_no_top_tie'])} | {v['mean_fixed_wrong_gap']:.4f} | {v['mean_dynamic_gap']:.4f} |")
lines+=['','## Example counterexamples: fixed K1-trained raw post-norm probe','','First ten IDs in sorted order for each class; IDs may overlap between classes only when logically possible. Full candidate-level evidence is in per_question.jsonl.','','| Category | IDs |','|---|---|']
name='post_norm_raw_trainK1_real'; ids=sorted(rr[name+'_evalK1']);a=rr[name+'_evalK1'];b=rr[name+'_evalK2'];n1=rr['native_K1'];n2=rr['native_K2'];cases={'native K1 correct but probe K1 wrong':[i for i in ids if n1[i]['correct'] and not a[i]['correct']],'native K2 correct but probe K2 wrong':[i for i in ids if n2[i]['correct'] and not b[i]['correct']],'native rescue but probe fails to rescue':[i for i in ids if n1[i]['group']=='rescue' and not (not a[i]['correct'] and b[i]['correct'])],'probe damages K1 to K2':[i for i in ids if a[i]['correct'] and not b[i]['correct']]}
